class TestMeshNodeSchema:
    """Validate Pydantic v2 schema enforcement with security constraints."""

    def test_valid_schema_creation(self, valid_node_data: Dict[str, Any]):
        """Verify a valid payload passes all schema validators."""
        schema = MeshNodeSchema(**valid_node_data)
        assert schema.agent_id == "agent-alpha-42"
        assert schema.host == "192.168.1.100"
        assert schema.port == 9001
        assert "embedding" in schema.capabilities

    @pytest.mark.parametrize("invalid_host,expected_error", [
        ("256.1.2.3", "octet out of range"),      # Octet > 255
        ("192.168.01.1", "leading zeros"),         # Leading zeros
        ("0.0.0.0", "reserved address"),           # Wildcard
        ("127.0.0.1", "loopback"),                 # Loopback
        ("10.0.0.0", "reserved address"),          # Private network base
        ("172.16.0.0", "reserved address"),        # Private network base
        ("192.168.0.0", "reserved address"),       # Private network base
        ("224.0.0.1", "multicast"),                # Multicast
        ("169.254.1.1", "link-local"),             # Link-local
        ("not-an-ip", "invalid IPv4"),             # Non-IP string
        ("", "empty string"),                      # Empty
        ("1.2.3.4.5", "too many octets"),          # Extra octet
        ("1.2.3", "too few octets"),               # Missing octets
    ])
    def test_invalid_host_rejection(self, valid_node_data: Dict[str, Any], 
                                     invalid_host: str, expected_error: str):
        """Verify all invalid host formats are rejected with appropriate errors."""
        data = {**valid_node_data, "host": invalid_host}
        with pytest.raises(ValueError) as exc_info:
            MeshNodeSchema(**data)
        assert expected_error.lower() in str(exc_info.value).lower()

    @pytest.mark.parametrize("invalid_port", [
        -1, 0, 65536, 99999, None, "not-a-port", 3.14
    ])
    def test_invalid_port_rejection(self, valid_node_data: Dict[str, Any], 
                                     invalid_port: Any):
        """Verify port validation rejects out-of-range and non-integer values."""
        data = {**valid_node_data, "port": invalid_port}
        with pytest.raises((ValueError, TypeError)):
            MeshNodeSchema(**data)

    def test_empty_agent_id_rejection(self, valid_node_data: Dict[str, Any]):
        """Agent ID must be non-empty string."""
        data = {**valid_node_data, "agent_id": ""}
        with pytest.raises(ValueError, match="agent_id"):
            MeshNodeSchema(**data)

    def test_duplicate_capabilities_deduplication(self, valid_node_data: Dict[str, Any]):
        """Capabilities list should be deduplicated automatically."""
        data = {**valid_node_data, "capabilities": ["embedding", "embedding", "classification"]}
        schema = MeshNodeSchema(**data)
        assert schema.capabilities == ["embedding", "classification"]

    def test_missing_optional_fields(self, valid_node_data: Dict[str, Any]):
        """Verify optional fields have sensible defaults."""
        del valid_node_data["public_key"]
        del valid_node_data["version"]
        schema = MeshNodeSchema(**valid_node_data)
        assert schema.public_key == ""
        assert schema.version == "0.0.0"

    @given(st.text(min_size=1, max_size=100))
    def test_agent_id_accepts_valid_strings(self, agent_id: str):
        """Property-based: any non-empty string should be accepted as agent_id."""
        assume(len(agent_id.strip()) > 0)
        data = {
            "agent_id": agent_id,
            "host": "10.0.0.1",
            "port": 9000,
            "capabilities": ["test"],
        }
        schema = MeshNodeSchema(**data)
        assert schema.agent_id == agent_id

    def test_model_dump_roundtrip(self, valid_node_data: Dict[str, Any]):
        """Schema serialization and deserialization should be lossless."""
        schema = MeshNodeSchema(**valid_node_data)
        dumped = schema.model_dump()
        restored = MeshNodeSchema(**dumped)
        assert restored == schema


