class TestMeshNode:
    """Validate MeshNode class behavior: registration, heartbeat, serialization."""

    def test_node_initialization(self, valid_node_data: Dict[str, Any]):
        """Verify node initializes with correct state."""
        node = MeshNode(**valid_node_data)
        assert node.agent_id == "agent-alpha-42"
        assert node.is_alive is True
        assert node.last_seen > 0
        assert isinstance(node.schema, MeshNodeSchema)

    def test_node_heartbeat_update(self, valid_node: MeshNode):
        """Heartbeat should update last_seen timestamp."""
        original_seen = valid_node.last_seen
        time.sleep(0.01)  # Ensure timestamp difference
        valid_node.heartbeat()
        assert valid_node.last_seen > original_seen
        assert valid_node.is_alive is True

    def test_node_stale_detection(self, valid_node: MeshNode):
        """Node should be marked stale after timeout period."""
        # Force last_seen to be old
        valid_node.last_seen = time.time() - 100  # 100 seconds ago
        assert valid_node.is_alive is False

    def test_node_serialization(self, valid_node: MeshNode):
        """Node should serialize to/from JSON correctly."""
        serialized = valid_node.to_json()
        assert isinstance(serialized, str)
        
        deserialized = MeshNode.from_json(serialized)
        assert deserialized.agent_id == valid_node.agent_id
        assert deserialized.host == valid_node.host
        assert deserialized.port == valid_node.port
        assert deserialized.capabilities == valid_node.capabilities

    def test_node_persistence(self, valid_node: MeshNode, tmp_path: Path):
        """Node should persist to disk and be recoverable."""
        filepath = tmp_path / "test_node.json"
        valid_node.save(filepath)
        assert filepath.exists()
        
        loaded = MeshNode.load(filepath)
        assert loaded.agent_id == valid_node.agent_id
        assert loaded.last_seen == valid_node.last_seen

    def test_node_equality(self):
        """Nodes with same agent_id should be equal."""
        node1 = MeshNode(agent_id="test-1", host="10.0.0.1", port=9000, capabilities=[])
        node2 = MeshNode(agent_id="test-1", host="10.0.0.2", port=9001, capabilities=[])
        assert node1 == node2
        assert hash(node1) == hash(node2)

    def test_node_inequality(self):
        """Nodes with different agent_ids should not be equal."""
        node1 = MeshNode(agent_id="test-1", host="10.0.0.1", port=9000, capabilities=[])
        node2 = MeshNode(agent_id="test-2", host="10.0.0.1", port=9000, capabilities=[])
        assert node1 != node2

    def test_node_capability_matching(self, valid_node: MeshNode):
        """Node should correctly report capability support."""
        assert valid_node.has_capability("embedding") is True
        assert valid_node.has_capability("unknown") is False

    def test_node_malformed_json_deserialization(self):
        """Deserialization should reject malformed JSON."""
        with pytest.raises((json.JSONDecodeError, ValueError)):
            MeshNode.from_json("{invalid json}")
        
        with pytest.raises((json.JSONDecodeError, ValueError)):
            MeshNode.from_json("")

    def test_node_missing_fields_deserialization(self):
        """Deserialization should reject JSON missing required fields."""
        incomplete = json.dumps({"agent_id": "test"})  # Missing host, port, capabilities
        with pytest.raises(ValueError):
            MeshNode.from_json(incomplete)


