class TestChaosEngineering:
    """Validate mesh resilience under fault conditions."""

    @pytest.mark.asyncio
    async def test_mesh_recovery_after_corrupt_state_file(self, mesh_with_nodes: AgentMesh):
        """Mesh should recover gracefully from corrupt state files."""
        # Save valid state
        await mesh_with_nodes.save_state()
        
        # Corrupt the state file
        state_file = Path(MESH_DIR) / f"{mesh_with_nodes.node_id}_state.json"
        state_file.write_text("{corrupt json")
        
        # Attempt to load - should not crash
        new_mesh = AgentMesh(node_id="test-mesh")
        await new_mesh.load_state()
        # Should have empty state after corrupt file
        assert len(new_mesh.nodes) == 0

    @pytest.mark.asyncio
    async def test_mesh_handles_missing_state_file(self):
        """Mesh should handle missing state file gracefully."""
        mesh = AgentMesh(node_id="nonexistent-mesh")
        await mesh.load_state()  # Should not raise
        assert len(mesh.nodes) == 0

    @pytest.mark.asyncio
    async def test_mesh_handles_concurrent_start_stop(self):
        """Mesh should handle rapid start/stop cycles."""
        mesh = AgentMesh(node_id="chaos-mesh")
        
        for _ in range(10):
            await mesh.start()
            await asyncio.sleep(0.01)
            await mesh.stop()
        
        assert mesh.is_running is False

    @pytest.mark.asyncio
    async def test_mesh_handles_many_nodes(self):
        """Mesh should handle registration of many nodes."""
        mesh = AgentMesh(node_id="stress-mesh")
        
        # Register 1000 nodes
        for i in range(1000):
            node = MeshNode(
                agent_id=f"stress-{i}",
                host="10.0.0.1",
                port=9000 + i,
                capabilities=["stress-test"],
            )
            await mesh.register_node(node)
        
        assert len(mesh.nodes) == 1000
        
        # Discovery should still work
        peers = await mesh.discover_peers()
        assert len(peers) == 1000

    @pytest.mark.asyncio
    async def test_mesh_handles_node_flapping(self):
        """Mesh should handle nodes that rapidly register/unregister."""
        mesh = AgentMesh(node_id="flap-mesh")
        
        async def flap_node(agent_id: str):
            for _ in range(10):
                node = MeshNode(
                    agent_id=agent_id,
                    host="10.0.0.1",
                    port=9000,
                    capabilities=["flapping"],
                )
                await mesh.register_node(node)
                await asyncio.sleep(0.01)
                # Simulate node going offline
                mesh.nodes[agent_id].last_seen = time.time() - 1000
                await mesh.cleanup_stale_nodes(timeout=1)
        
        # Run multiple flapping nodes concurrently
        tasks = [flap_node(f"flap-{i}") for i in range(5)]
        await asyncio.gather(*tasks)
        
        # Mesh should still be operational
        assert mesh.is_running is False  # Not started
        assert len(mesh.nodes) >= 0  # Some may have been cleaned up


