class MeshStateMachine(RuleBasedStateMachine):
    """Stateful testing of mesh operations using Hypothesis."""
    
    def __init__(self):
        super().__init__()
        self.mesh = AgentMesh(node_id="stateful-test")
        self.node_counter = 0
    
    @rule(
        host=st.ip_addresses(v=4).map(str),
        port=st.integers(min_value=1024, max_value=65535),
        capabilities=st.lists(st.text(min_size=1, max_size=20), max_size=5),
    )
    async def register_node(self, host: str, port: int, capabilities: List[str]):
        """Register a node with random properties."""
        # Skip private IPs as they're rejected by schema
        assume(not host.startswith(("10.", "172.16.", "192.168.", "127.", "0.", "169.254.", "224.")))
        
        node = MeshNode(
            agent_id=f"prop-{self.node_counter}",
            host=host,
            port=port,
            capabilities=list(set(capabilities)),  # Deduplicate
        )
        self.node_counter += 1
        await self.mesh.register_node(node)
    
    @invariant()
    def nodes_are_unique(self):
        """All nodes in mesh should have unique agent_ids."""
        agent_ids = list(self.mesh.nodes.keys())
        assert len(agent_ids) == len(set(agent_ids))
    
    @invariant()
    def node_count_is_non_negative(self):
        """Node count should never be negative."""
